/**
 * Typed data-access boundary for the research console.
 *
 * Every function here returns exactly the shape a future real backend API
 * would return; today they read from bundled, statically-imported JSON
 * fixture files generated by `scripts/export_frontend_fixtures.py` (see
 * `meta.json`, whose `is_fixture_data: true` flag this module re-exports).
 * This is a fixture-backed implementation of the data-access contract, not
 * a separate mock architecture: swapping these function bodies for
 * `fetch()` calls against a real API, once one exists, requires no change
 * to any caller, because the return types and function signatures are
 * exactly what the API boundary should look like.
 *
 * The frontend must never present this data as if it came from a live
 * experiment; every page that renders it also renders the fixture-data
 * notice (see `components/FixtureNotice.tsx`).
 */
import experimentsData from "./fixtures/experiments.json";
import runsData from "./fixtures/runs.json";
import diagnosticsData from "./fixtures/diagnostics.json";
import retrievalResultsData from "./fixtures/retrieval_results.json";
import robustnessData from "./fixtures/robustness.json";
import summariesData from "./fixtures/summaries.json";
import metaData from "./fixtures/meta.json";
import type {
  ExperimentDefinition,
  ExperimentRun,
  FixtureMeta,
  ReliabilityDiagnostic,
  RetrievalEvaluationResult,
  RunRobustnessBundle,
  RunSummaryBundle,
} from "../types/domain";

const experiments = experimentsData as ExperimentDefinition[];
const runs = runsData as Record<string, ExperimentRun>;
const diagnostics = diagnosticsData as Record<string, Record<string, ReliabilityDiagnostic>>;
const retrievalResults = retrievalResultsData as Record<
  string,
  Record<string, RetrievalEvaluationResult[]>
>;
const robustness = robustnessData as Record<string, RunRobustnessBundle>;
const summaries = summariesData as Record<string, RunSummaryBundle>;

export const fixtureMeta: FixtureMeta = metaData as FixtureMeta;

export function listExperiments(): ExperimentDefinition[] {
  return experiments;
}

export function getExperiment(experimentId: string): ExperimentDefinition | undefined {
  return experiments.find((e) => e.experiment_id === experimentId);
}

export function listRunsForExperiment(experimentId: string): ExperimentRun[] {
  return Object.values(runs).filter((run) => run.experiment_id === experimentId);
}

export function listAllRuns(): ExperimentRun[] {
  return Object.values(runs);
}

export function getRun(runId: string): ExperimentRun | undefined {
  return runs[runId];
}

export function getDiagnosticsForRun(runId: string): Record<string, ReliabilityDiagnostic> {
  return diagnostics[runId] ?? {};
}

export function getDiagnosticForTestCase(
  runId: string,
  testCaseId: string,
): ReliabilityDiagnostic | undefined {
  return diagnostics[runId]?.[testCaseId];
}

export function getRetrievalResultsForRun(
  runId: string,
): Record<string, RetrievalEvaluationResult[]> {
  return retrievalResults[runId] ?? {};
}

export function getRobustnessForRun(runId: string): RunRobustnessBundle | undefined {
  return robustness[runId];
}

export function getSummaryForRun(runId: string): RunSummaryBundle | undefined {
  return summaries[runId];
}
